def transform(grid):
    """Rotate each 2x2 block's four diagonal marker colors and extend their rays."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))
    for r, c in blocks:
        # Diagonal marker locations around the block.
        pos = {
            "NW": (r - 1, c - 1),
            "NE": (r - 1, c + 2),
            "SW": (r + 2, c - 1),
            "SE": (r + 2, c + 2),
        }
        colors = {k: grid[rr][cc] if 0 <= rr < h and 0 <= cc < w else 0
                  for k, (rr, cc) in pos.items()}
        # Each ray goes outward from its corner, with colors rotated clockwise.
        rays = [
            ("NW", colors["SW"], -1, -1),
            ("NE", colors["NW"], -1, 1),
            ("SE", colors["NE"], 1, 1),
            ("SW", colors["SE"], 1, -1),
        ]
        for corner, color, dr, dc in rays:
            rr, cc = pos[corner]
            while 0 <= rr < h and 0 <= cc < w:
                # Stop a ray before it reaches the one-cell margin of another 2x2 block.
                near_other_block = any(
                    (br, bc) != (r, c)
                    and abs(rr - ar) <= 1 and abs(cc - ac) <= 1
                    for br, bc in blocks
                    for ar in (br, br + 1) for ac in (bc, bc + 1)
                )
                if near_other_block:
                    break
                # Keep the central blocks intact where diagonal rays cross them.
                if grid[rr][cc] != 2:
                    out[rr][cc] = color
                rr += dr
                cc += dc
    return out

